ALTER TABLE public.rh_avaliacoes ADD COLUMN IF NOT EXISTS manual_attempts int NOT NULL DEFAULT 0;
ALTER TABLE public.rh_avaliacoes ADD COLUMN IF NOT EXISTS claim_token uuid;
ALTER TABLE public.rh_avaliacoes ADD COLUMN IF NOT EXISTS evaluating boolean NOT NULL DEFAULT false;
ALTER TABLE public.rh_avaliacoes ADD COLUMN IF NOT EXISTS ai_error text;
ALTER TABLE public.rh_settings ADD COLUMN IF NOT EXISTS ai_blocked_reason text;
CREATE INDEX rh_candidatos_search_idx ON public.rh_candidatos USING gin ((lower(coalesce(nome,rascunho->>'nome','') || ' ' || instagram_username)) gin_trgm_ops);
CREATE INDEX rh_candidatos_rank_idx ON public.rh_candidatos(aceita_condicoes, created_at DESC, id);
CREATE OR REPLACE FUNCTION public.rh_admin_context() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; RETURN jsonb_build_object('password_set',public.rh_area_password_set('rh'),'counts',public.rh_counts(),'vagas',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'titulo',titulo,'resumo',resumo) ORDER BY created_at),'[]') FROM rh_vagas WHERE ativo)); END $$;
CREATE OR REPLACE FUNCTION public.rh_list_candidatos(p_search text DEFAULT NULL,p_status text DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE q text := left(trim(coalesce(p_search,'')),120); BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; RETURN coalesce((SELECT jsonb_agg(x ORDER BY x.nao_topa,x.nota DESC NULLS LAST,x.created_at DESC,x.id) FROM (SELECT c.id,coalesce(c.nome,c.rascunho->>'nome','Sem nome') nome,c.instagram_username,coalesce(c.whatsapp,c.rascunho->>'whatsapp') whatsapp,coalesce(c.bairro,c.rascunho->>'bairro') bairro,coalesce(c.transporte,c.rascunho->>'transporte') transporte,coalesce(c.status,'incompleto') status,c.observacao,(c.aceita_condicoes IS FALSE) nao_topa,a.nota,a.parcial,a.evaluating,a.detalhe->'permanencia'->>'media_meses' media_meses,c.created_at FROM rh_candidatos c LEFT JOIN rh_avaliacoes a ON a.candidato_id=c.id WHERE (q='' OR lower(coalesce(c.nome,c.rascunho->>'nome','') || ' ' || c.instagram_username) LIKE '%' || lower(replace(replace(replace(q,'\','\\'),'%','\%'),'_','\_')) || '%') AND (p_status IS NULL OR coalesce(c.status,'incompleto')=p_status) ORDER BY (c.aceita_condicoes IS FALSE),a.nota DESC NULLS LAST,c.created_at DESC,c.id LIMIT least(greatest(coalesce(p_limit,50),1),200) OFFSET greatest(coalesce(p_offset,0),0)) x),'[]'); END $$;
CREATE OR REPLACE FUNCTION public.rh_candidate_detail(p_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; RETURN (SELECT jsonb_build_object('password_set',public.rh_area_password_set('rh'),'candidato',to_jsonb(c),'experiencias',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.ordem) FROM rh_experiencias e WHERE e.candidato_id=c.id),'[]'),'respostas',coalesce((SELECT jsonb_agg(jsonb_build_object('ordem',r.ordem,'mensagem_cliente',r.mensagem_cliente,'resposta',r.resposta,'contexto',s.contexto) ORDER BY r.ordem) FROM rh_respostas_teste r LEFT JOIN rh_cenarios s ON s.id=r.cenario_id WHERE r.candidato_id=c.id),'[]'),'avaliacao',(SELECT to_jsonb(a)-'claim_token' FROM rh_avaliacoes a WHERE a.candidato_id=c.id)) FROM rh_candidatos c WHERE c.id=p_id); END $$;
CREATE OR REPLACE FUNCTION public.rh_update_candidato(p_id uuid,p_status text,p_observacao text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF p_status NOT IN ('novo','em_analise','chamado','aprovado','reprovado') THEN RAISE EXCEPTION 'Status inválido'; END IF; UPDATE rh_candidatos SET status=p_status,observacao=left(p_observacao,3000),updated_at=now() WHERE id=p_id AND submitted_at IS NOT NULL AND (status IS DISTINCT FROM p_status OR observacao IS DISTINCT FROM left(p_observacao,3000)); RETURN EXISTS(SELECT 1 FROM rh_candidatos WHERE id=p_id AND submitted_at IS NOT NULL); END $$;
CREATE OR REPLACE FUNCTION public.rh_admin_config() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; RETURN jsonb_build_object('settings',(SELECT to_jsonb(s) FROM rh_settings s WHERE id=1),'vagas',(SELECT coalesce(jsonb_agg(to_jsonb(v) ORDER BY created_at),'[]') FROM rh_vagas v WHERE ativo),'cenarios',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY ordem),'[]') FROM rh_cenarios c WHERE ativo),'bairros',(SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY loja,bairro),'[]') FROM rh_bairros_proximos b),'instancias',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',label)),'[]') FROM whatsapp_numbers_safe WHERE provider='uazapi')); END $$;
CREATE OR REPLACE FUNCTION public.rh_score_claim(p_id uuid,p_manual boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a rh_avaliacoes%ROWTYPE; t uuid := gen_random_uuid(); BEGIN IF NOT EXISTS(SELECT 1 FROM rh_candidatos WHERE id=p_id AND submitted_at IS NOT NULL) THEN RETURN jsonb_build_object('ok',false,'message','Cadastro ainda não enviado.'); END IF; INSERT INTO rh_avaliacoes(candidato_id) VALUES(p_id) ON CONFLICT DO NOTHING; SELECT * INTO a FROM rh_avaliacoes WHERE candidato_id=p_id FOR UPDATE; IF a.evaluating THEN RETURN jsonb_build_object('ok',false,'message','Avaliação já iniciada. Não repetimos chamadas incertas.'); END IF; IF NOT p_manual AND a.ai_attempted_at IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'message','Este cadastro já foi avaliado.'); END IF; IF p_manual AND a.manual_attempts>=3 THEN RETURN jsonb_build_object('ok',false,'message','Limite de 3 reavaliações atingido.'); END IF; UPDATE rh_avaliacoes SET claim_token=t,evaluating=true,ai_attempted_at=now(),manual_attempts=manual_attempts+CASE WHEN p_manual THEN 1 ELSE 0 END,updated_at=now() WHERE candidato_id=p_id; RETURN jsonb_build_object('ok',true,'token',t,'candidato',(SELECT jsonb_build_object('aceita_condicoes',aceita_condicoes,'ja_trabalhou',ja_trabalhou,'transporte',transporte,'bairro',bairro,'computador',computador,'situacao',situacao) FROM rh_candidatos WHERE id=p_id),'experiencias',coalesce((SELECT jsonb_agg(jsonb_build_object('duracao_meses',duracao_meses)) FROM rh_experiencias WHERE candidato_id=p_id),'[]'),'respostas',coalesce((SELECT jsonb_agg(jsonb_build_object('ordem',r.ordem,'resposta',r.resposta,'mensagem',r.mensagem_cliente,'contexto',c.contexto,'gabarito',c.gabarito) ORDER BY r.ordem) FROM rh_respostas_teste r LEFT JOIN rh_cenarios c ON c.id=r.cenario_id WHERE r.candidato_id=p_id),'[]'),'settings',(SELECT to_jsonb(s) FROM rh_settings s WHERE id=1),'bairros',coalesce((SELECT jsonb_agg(jsonb_build_object('bairro_norm',bairro_norm,'pontos',pontos,'loja',loja)) FROM rh_bairros_proximos),'[]')); END $$;
CREATE OR REPLACE FUNCTION public.rh_score_finish(p_id uuid,p_token uuid,p_result jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE rh_avaliacoes SET nota=round(greatest(0,least(100,(p_result->>'nota')::numeric)),1),parcial=(p_result->>'parcial')::boolean,detalhe=p_result->'detalhe',resumo_ia=p_result->>'resumo_ia',alertas=p_result->'alertas',ai_error=p_result->>'ai_error',evaluating=false,claim_token=NULL,updated_at=now() WHERE candidato_id=p_id AND claim_token=p_token AND evaluating; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.rh_admin_context(), public.rh_list_candidatos(text,text,int,int),public.rh_candidate_detail(uuid),public.rh_update_candidato(uuid,text,text),public.rh_admin_config() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rh_admin_context(), public.rh_list_candidatos(text,text,int,int),public.rh_candidate_detail(uuid),public.rh_update_candidato(uuid,text,text),public.rh_admin_config() TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.rh_score_claim(uuid,boolean),public.rh_score_finish(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.rh_score_claim(uuid,boolean),public.rh_score_finish(uuid,uuid,jsonb) TO service_role;